// The whole World English Bible. The list of books (with every chapter's verse count) is small
// and always loaded; each book's text is loaded the first time it is opened and then kept.
// Generated by scripts/build-bible.mjs into data/bible/. No React here: see components/bible.ts.
import meta from "./bible/index.json";
import { BOOK_FILES, type BookText } from "./bible/files";
import type { StudyNote, Verse, VerseRef } from "./schema";

export interface BookInfo {
  /** Three-character id, e.g. "JHN". */
  id: string;
  /** Name as shown, e.g. "John", "1 Samuel", "Psalms". */
  name: string;
  /** Abbreviation from the source, e.g. "Jhn". */
  short: string;
  /** Canonical position: Genesis is 1, Revelation is 66. */
  order: number;
  /** Verses in each chapter (index 0 is chapter 1). */
  verses: number[];
  testament: "old" | "new";
}

/** Where the text comes from, for Settings and the README. */
export const TRANSLATION = meta.translation;
/** 66 books, 1,189 chapters, 31,103 verse numbers (31,098 with text). */
export const BIBLE_TOTALS = meta.totals;

/** Genesis to Malachi are the Old Testament's 39 books. */
const OLD_TESTAMENT_BOOKS = 39;

export const BOOKS: BookInfo[] = meta.books.map(
  (b, i): BookInfo => ({
    ...b,
    order: i + 1,
    testament: i < OLD_TESTAMENT_BOOKS ? "old" : "new",
  }),
);

const BY_ID = new Map(BOOKS.map((b) => [b.id, b]));
const BY_NAME = new Map(BOOKS.map((b) => [b.name, b]));
const OMITTED: Record<string, string> = meta.omitted;
const TITLES: Record<string, string> = meta.titles;

const key = (bookId: string, chapter: number, verse?: number) =>
  verse === undefined ? `${bookId}.${chapter}` : `${bookId}.${chapter}.${verse}`;

// ---------------------------------------------------------------------------------------------
// Books by name

/** Lowercase, without spaces or dots, with "First John", "I John" or "1st John" as "1john". */
function squash(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/^(first|1st|i)\s+/, "1")
    .replace(/^(second|2nd|ii)\s+/, "2")
    .replace(/^(third|3rd|iii)\s+/, "3")
    .replace(/[\s.]+/g, "");
}

/** Other names and abbreviations people type, by book id. */
const ALIASES: Record<string, string[]> = {
  GEN: ["gn"],
  EXO: ["ex", "exod"],
  LEV: ["lv"],
  NUM: ["nm", "nb"],
  DEU: ["dt", "deut"],
  JDG: ["judg", "jdgs"],
  RUT: ["rth"],
  PSA: ["psalm", "ps", "pss", "psm"],
  PRO: ["prov", "prv", "pr"],
  ECC: ["eccl", "eccles", "qoheleth"],
  SNG: ["song", "songofsongs", "canticles", "sos"],
  EZK: ["ezek"],
  MAT: ["mt", "matt"],
  MRK: ["mk", "mar"],
  LUK: ["lk"],
  JHN: ["jn", "jhn"],
  ACT: ["acts"],
  PHP: ["phil"],
  PHM: ["philem"],
  JAS: ["jas"],
  REV: ["revelations", "rv", "apocalypse"],
};

const EXACT = new Map<string, BookInfo>();
for (const book of BOOKS) {
  for (const name of [book.name, book.id, book.short, ...(ALIASES[book.id] ?? [])]) {
    const k = squash(name);
    if (!EXACT.has(k)) EXACT.set(k, book);
  }
}

/**
 * The book someone means: "John", "jn", "Psalm", "1 cor", "Song of Songs", "first john".
 * An exact name or abbreviation wins; otherwise the first book (in Bible order) whose name
 * starts with what was typed.
 */
export function findBook(text: string): BookInfo | undefined {
  const wanted = squash(text);
  if (!wanted) return undefined;
  return (
    EXACT.get(wanted) ??
    (wanted.length >= 2 ? BOOKS.find((b) => squash(b.name).startsWith(wanted)) : undefined)
  );
}

export function bookById(id: string): BookInfo | undefined {
  return BY_ID.get(id);
}

/** A book from a stored name. Names saved by earlier versions ("Psalms", "John") match as is. */
export function bookOf(name: string): BookInfo | undefined {
  return BY_NAME.get(name) ?? findBook(name);
}

// ---------------------------------------------------------------------------------------------
// Verses, using only the book list (no text needed)

/** Verses in a chapter, or 0 when the book has no such chapter. */
export function verseCount(book: BookInfo, chapter: number): number {
  return book.verses[chapter - 1] ?? 0;
}

/**
 * The translator's footnote for a verse number this edition leaves out (e.g. Acts 8:37), or
 * undefined for a verse that has text.
 */
export function omittedNote(ref: VerseRef): string | undefined {
  const book = bookOf(ref.book);
  return book ? OMITTED[key(book.id, ref.chapter, ref.verse)] : undefined;
}

/** A Psalm's title as published ("A Psalm by David."), shown above its first verse. */
export function chapterTitle(book: BookInfo, chapter: number): string | undefined {
  return TITLES[key(book.id, chapter)];
}

function hasText(book: BookInfo, chapter: number, verse: number): boolean {
  return (
    verse >= 1 &&
    verse <= verseCount(book, chapter) &&
    OMITTED[key(book.id, chapter, verse)] === undefined
  );
}

/** The next (+1) or previous (-1) verse with text, across chapters and books. */
function step(ref: VerseRef, direction: 1 | -1): VerseRef | undefined {
  let book = bookOf(ref.book);
  if (!book) return undefined;
  let chapter = ref.chapter;
  let verse = ref.verse;
  for (;;) {
    verse += direction;
    if (verse > verseCount(book, chapter)) {
      chapter += 1;
      verse = 1;
      if (chapter > book.verses.length) {
        const following: BookInfo | undefined = BOOKS[book.order];
        if (!following) return undefined;
        book = following;
        chapter = 1;
      }
    } else if (verse < 1) {
      chapter -= 1;
      if (chapter < 1) {
        const before: BookInfo | undefined = BOOKS[book.order - 2];
        if (!before) return undefined;
        book = before;
        chapter = book.verses.length;
      }
      verse = verseCount(book, chapter);
    }
    if (hasText(book, chapter, verse)) return { book: book.name, chapter, verse };
  }
}

/** The verse after this one: the next chapter after a chapter's end, the next book after a book's. */
export function nextRef(ref: VerseRef): VerseRef | undefined {
  return step(ref, 1);
}

/** The verse before this one, back across chapters and books. */
export function previousRef(ref: VerseRef): VerseRef | undefined {
  return step(ref, -1);
}

const firstBook = BOOKS[0]!;
const lastBook = BOOKS[BOOKS.length - 1]!;
/** Genesis 1:1 */
export const FIRST_REF: VerseRef = { book: firstBook.name, chapter: 1, verse: 1 };
/** Revelation 22:21 */
export const LAST_REF: VerseRef = {
  book: lastBook.name,
  chapter: lastBook.verses.length,
  verse: verseCount(lastBook, lastBook.verses.length),
};

/**
 * A reference as this Bible spells it, or undefined when there is no such verse. A book name
 * saved by an earlier version (or typed loosely) is matched to the book; a verse number this
 * edition leaves out moves on to the next verse with text.
 */
export function normalizeRef(ref: { book: string; chapter: number; verse: number }): VerseRef | undefined {
  const book = bookOf(ref.book);
  if (!book || !Number.isInteger(ref.chapter) || !Number.isInteger(ref.verse)) return undefined;
  if (ref.verse < 1 || ref.verse > verseCount(book, ref.chapter)) return undefined;
  const clean = { book: book.name, chapter: ref.chapter, verse: ref.verse };
  return hasText(book, ref.chapter, ref.verse) ? clean : (nextRef(clean) ?? previousRef(clean));
}

/** The last verse with text in a chapter. */
export function lastOfChapter(book: BookInfo, chapter: number): VerseRef {
  let verse = verseCount(book, chapter);
  while (verse > 1 && !hasText(book, chapter, verse)) verse -= 1;
  return { book: book.name, chapter, verse };
}

// ---------------------------------------------------------------------------------------------
// Book text: loaded once, then kept

const texts = new Map<string, BookText>();
const pending = new Map<string, Promise<BookText>>();
const loadedListeners = new Set<() => void>();

/** A book's text if it has been loaded, else undefined. */
export function peekBook(id: string): BookText | undefined {
  return texts.get(id);
}

/** Load a book's text (once; later calls get the same text). */
export function loadBook(id: string): Promise<BookText> {
  const done = texts.get(id);
  if (done) return Promise.resolve(done);
  const running = pending.get(id);
  if (running) return running;
  const loader = BOOK_FILES[id];
  if (!loader) return Promise.reject(new Error(`No book ${id}`));
  const job = loader()
    .then((module) => {
      const text = Array.isArray(module) ? module : module.default;
      texts.set(id, text);
      loadedListeners.forEach((listener) => listener());
      return text;
    })
    .finally(() => pending.delete(id));
  pending.set(id, job);
  return job;
}

/** Called whenever another book finishes loading. Returns the unsubscribe function. */
export function onBookLoaded(listener: () => void): () => void {
  loadedListeners.add(listener);
  return () => loadedListeners.delete(listener);
}

function verseFrom(book: BookInfo, chapter: number, verse: number, text: string): Verse {
  return {
    id: key(book.id, chapter, verse),
    book: book.name,
    bookOrder: book.order,
    chapter,
    verse,
    text,
    hasNote: false,
  };
}

/** A verse with its text, if its book is loaded and the verse has text. */
export function getVerse(ref: VerseRef): Verse | undefined {
  const book = bookOf(ref.book);
  const text = book ? peekBook(book.id)?.[ref.chapter - 1]?.[ref.verse - 1] : undefined;
  return book && text ? verseFrom(book, ref.chapter, ref.verse, text) : undefined;
}

/** A verse with its text, loading its book first if needed. */
export async function fetchVerse(ref: VerseRef): Promise<Verse | undefined> {
  const book = bookOf(ref.book);
  if (!book) return undefined;
  await loadBook(book.id);
  return getVerse(ref);
}

/** Every verse of a chapter that has text, in order, if its book is loaded. */
export function chapterVerses(book: BookInfo, chapter: number): Verse[] | undefined {
  const text = peekBook(book.id)?.[chapter - 1];
  if (!text) return undefined;
  const out: Verse[] = [];
  text.forEach((line, i) => {
    if (line) out.push(verseFrom(book, chapter, i + 1, line));
  });
  return out;
}

/** Marks the verses that have a prepared study note. */
export function withNotes(verses: Verse[], notes: StudyNote[]): Verse[] {
  if (notes.length === 0) return verses;
  const noted = new Set(notes.map((n) => `${n.book} ${n.chapter}:${n.verse}`));
  return verses.map((v) =>
    noted.has(`${v.book} ${v.chapter}:${v.verse}`) ? { ...v, hasNote: true } : v,
  );
}

// ---------------------------------------------------------------------------------------------
// References typed into Search

export type Passage =
  | { kind: "verse"; book: BookInfo; chapter: number; verse: number; end: number }
  | { kind: "chapter"; book: BookInfo; chapter: number }
  | { kind: "missing"; title: string; body: string };

/**
 * Read a reference: "John 3:16", "John 3:16-18", "Psalm 23", "Romans", "Jude 3" (a one-chapter
 * book takes the verse alone). Returns null when no book matches; "missing" with what to say
 * when the book matches but the chapter or verse isn't in it.
 */
export function parsePassage(query: string): Passage | null {
  const match = /^\s*(.*?)\s*(?:(\d+)(?:\s*[:.]\s*(\d+)(?:\s*[-–]\s*(\d+))?)?)?\s*$/.exec(query);
  if (!match) return null;
  const [, name = "", chapterText, verseText, endText] = match;
  // A leading number belongs to the book name ("1 John"), so the name must have letters.
  if (!/[a-z]/i.test(name)) return null;
  const book = findBook(name);
  if (!book) return null;
  const chapters = book.verses.length;
  let chapter = chapterText ? Number(chapterText) : 1;
  let verse = verseText ? Number(verseText) : undefined;
  let end = endText ? Number(endText) : verse;
  if (chapters === 1 && chapterText && verseText === undefined && chapter > 1) {
    // "Jude 3" is verse 3 of Jude's only chapter.
    verse = chapter;
    end = chapter;
    chapter = 1;
  }
  const label = `${book.name} ${chapter}`;
  if (chapter < 1 || chapter > chapters) {
    return {
      kind: "missing",
      title: `${label} isn't in the Bible`,
      body: `${book.name} has ${chapters === 1 ? "one chapter" : `${chapters} chapters`}.`,
    };
  }
  if (verse === undefined) return { kind: "chapter", book, chapter };
  const count = verseCount(book, chapter);
  if (verse < 1 || verse > count) {
    return {
      kind: "missing",
      title: `${label}:${verse} isn't in the Bible`,
      body: `${label} has ${count} verses.`,
    };
  }
  const note = OMITTED[key(book.id, chapter, verse)];
  if (note && (end ?? verse) <= verse) {
    return {
      kind: "missing",
      title: `${label}:${verse} has no text in the World English Bible`,
      body: `Translator's note: ${note}`,
    };
  }
  return { kind: "verse", book, chapter, verse, end: Math.min(Math.max(end ?? verse, verse), count) };
}

/** The verses a parsed reference covers, if its book is loaded. */
export function passageVerses(passage: Passage): Verse[] | undefined {
  if (passage.kind === "missing") return [];
  const verses = chapterVerses(passage.book, passage.chapter);
  if (!verses || passage.kind === "chapter") return verses;
  return verses.filter((v) => v.verse >= passage.verse && v.verse <= passage.end);
}

// ---------------------------------------------------------------------------------------------
// Keyword search over every verse

/** Lowercase with straight quotes, so "God's" finds "God’s". */
export function foldForSearch(text: string): string {
  return text.toLowerCase().replace(/[‘’]/g, "'").replace(/[“”]/g, '"');
}

const folded = new Map<string, string[][]>();

export interface SearchProgress {
  /** Matching verses found so far, in Bible order (at most `keep`). */
  hits: Verse[];
  /** How many verses match so far, including any beyond `keep`. */
  total: number;
  /** Books searched so far, of 66. */
  searched: number;
  done: boolean;
}

const nextTick = () => new Promise<void>((resolve) => setTimeout(resolve, 0));

/**
 * Find the verses that contain every word, book by book in Bible order. Results arrive through
 * `onProgress` after each book, and the work pauses between books so typing stays responsive.
 * Stops quietly when `cancelled()` turns true.
 */
export async function searchBible(
  words: string[],
  options: { keep: number; onProgress: (progress: SearchProgress) => void; cancelled: () => boolean },
): Promise<void> {
  const wanted = words.map(foldForSearch).filter(Boolean);
  const hits: Verse[] = [];
  let total = 0;
  if (wanted.length === 0) {
    options.onProgress({ hits, total, searched: BOOKS.length, done: true });
    return;
  }
  for (let i = 0; i < BOOKS.length; i++) {
    const book = BOOKS[i]!;
    // Start loading the next few books while this one is searched.
    for (const ahead of BOOKS.slice(i + 1, i + 4)) void loadBook(ahead.id).catch(() => undefined);
    const text = await loadBook(book.id);
    if (options.cancelled()) return;
    let lower = folded.get(book.id);
    if (!lower) {
      lower = text.map((chapter) => chapter.map(foldForSearch));
      folded.set(book.id, lower);
    }
    lower.forEach((chapter, c) =>
      chapter.forEach((line, v) => {
        if (!line || !wanted.every((word) => line.includes(word))) return;
        total += 1;
        if (hits.length < options.keep) hits.push(verseFrom(book, c + 1, v + 1, text[c]![v]!));
      }),
    );
    const done = i === BOOKS.length - 1;
    options.onProgress({ hits: [...hits], total, searched: i + 1, done });
    if (!done) await nextTick();
    if (options.cancelled()) return;
  }
}
